            {
              "type": "null"
            }
          ]
        },
        "title": {
          "title": "Title",
          "description": "建议短剧名称（若提供则作为优先剧名参考）",
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ]
        },
        "genre": {
          "title": "Genre",
          "description": "剧本题材分类（如：都市逆袭、甜宠虐恋、悬疑烧脑等）",
